-- Monotonic whole-set checkpoint for actual tag filter/page/count inputs.
CREATE TABLE knowledge_tag_statistics_scope_versions (tenant_id BIGINT NOT NULL CHECK(tenant_id>0),knowledge_base_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),PRIMARY KEY(tenant_id,knowledge_base_id));
INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,id,1 FROM knowledge_bases;
CREATE FUNCTION tag_statistics_knowledge_bases() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP<>'DELETE' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER tag_statistics_knowledge_bases AFTER INSERT OR UPDATE OR DELETE ON knowledge_bases FOR EACH ROW EXECUTE FUNCTION tag_statistics_knowledge_bases();
CREATE FUNCTION tag_statistics_knowledge_tags() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP<>'DELETE' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER tag_statistics_knowledge_tags AFTER INSERT OR UPDATE OR DELETE ON knowledge_tags FOR EACH ROW EXECUTE FUNCTION tag_statistics_knowledge_tags();
CREATE FUNCTION tag_statistics_knowledges() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP<>'DELETE' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER tag_statistics_knowledges AFTER INSERT OR UPDATE OR DELETE ON knowledges FOR EACH ROW EXECUTE FUNCTION tag_statistics_knowledges();
CREATE FUNCTION tag_statistics_chunks() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP<>'DELETE' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER tag_statistics_chunks AFTER INSERT OR UPDATE OR DELETE ON chunks FOR EACH ROW EXECUTE FUNCTION tag_statistics_chunks();
CREATE FUNCTION tag_statistics_relations() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,knowledge_base_id,1 FROM knowledges WHERE id=OLD.knowledge_id UNION SELECT tenant_id,knowledge_base_id,1 FROM knowledge_tags WHERE id=OLD.tag_id ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP<>'DELETE' THEN INSERT INTO knowledge_tag_statistics_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,knowledge_base_id,1 FROM knowledges WHERE id=NEW.knowledge_id UNION SELECT tenant_id,knowledge_base_id,1 FROM knowledge_tags WHERE id=NEW.tag_id ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=knowledge_tag_statistics_scope_versions.revision+1; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER tag_statistics_relations AFTER INSERT OR UPDATE OR DELETE ON knowledge_tag_relations FOR EACH ROW EXECUTE FUNCTION tag_statistics_relations();
